}"},{"rank":3,"score":25.794,"file_path":"internal/ui/workspaces/entry.go","start_line":45,"end_line":67,"focus_line":45,"snippet_start_line":45,"snippet_end_line":67,"symbol_start_line":45,"symbol_end_line":67,"language":"Go","kind":"function","symbol_id":"local/devdesk:Go:internal/ui/workspaces/entry.go:function:detectGitStatus","symbol_name":"detectGitStatus","qualified_name":"detectGitStatus","signature":"func detectGitStatus(entry *Entry)","signals":["graph:calls","graph:incoming","graph:callers","complete-symbol"],"snippet":"func detectGitStatus(entry *Entry) {
