// s'accorder sur leur hauteur.
func layoutTier(width, height int) tier {
	switch {
	case width >= wideMinWidth && height >= wideMinHeight:
		return tierWide
	case width >= standardMinWidth:
		return tierStandard
	default:
		return tierCompact
	}
}

