// stripANSI removes escape sequences so an assertion compares what is on
// screen rather than how it is coloured.
func stripANSI(s string) string {
	var b strings.Builder
	inEscape := false
	for _, r := range s {
		switch {
		case r == '\x1b':
			inEscape = true
		case inEscape && r == 'm':
			inEscape = false
		case !inEscape:
			b.WriteRune(r)
		}
	}
	return strings.TrimSpace(b.String())
}
